/* Token Launch Radar — design system
   One static page, no network, no framework. Deep-space navy with a phosphor-mint radar sweep;
   an editorial serif for display, a system sans for the UI, a mono for figures. */

:root {
  --bg: #070b16;
  --bg-2: #0b1120;
  --surface: #101830;
  --surface-2: #151f3a;
  --surface-3: #1b2748;
  --line: rgba(148, 184, 255, 0.14);
  --line-strong: rgba(148, 184, 255, 0.28);
  --text: #e9edf7;
  --muted: #8d99b8;
  --faint: #5b6785;
  --mint: #35e0a1;
  --mint-dim: rgba(53, 224, 161, 0.16);
  --gold: #f2c14e;
  --gold-dim: rgba(242, 193, 78, 0.14);
  --coral: #ff6b57;
  --coral-dim: rgba(255, 107, 87, 0.14);
  --mono: ui-monospace, "SF Mono", "Cascadia Code", Menlo, Consolas, monospace;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, "Helvetica Neue", Arial, sans-serif;
  --serif: "Iowan Old Style", Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }

body {
  background:
    radial-gradient(1200px 700px at 78% -10%, rgba(53, 224, 161, 0.10), transparent 55%),
    radial-gradient(900px 600px at -10% 110%, rgba(80, 130, 255, 0.10), transparent 55%),
    var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

::selection { background: rgba(53, 224, 161, 0.28); }
:focus-visible { outline: 2px solid var(--mint); outline-offset: 2px; border-radius: 4px; }

.mono { font-family: var(--mono); font-variant-numeric: tabular-nums; }
.up { color: var(--mint); }
.down { color: var(--coral); }
.flat { color: var(--muted); }

/* ------------------------------------------------ header */
.site-header {
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  padding: 18px 28px 0 28px;
}
.brand { display: flex; align-items: center; gap: 14px; min-width: 0; }
.brand-mark { flex: 0 0 auto; }
.brand h1 {
  font-family: var(--serif); font-weight: 600; font-size: 21px; letter-spacing: 0.06em;
  margin: 0; white-space: nowrap;
}
.brand h1 em { font-style: normal; color: var(--mint); }
.brand .tagline { margin: 1px 0 0 0; color: var(--muted); font-size: 11.5px; letter-spacing: 0.02em; }
.snapshot-chip {
  text-align: right; font-size: 11px; color: var(--muted); line-height: 1.5;
  border: 1px solid var(--line); border-radius: 10px; padding: 8px 12px; background: rgba(16, 24, 48, 0.6);
  max-width: 380px;
}
.snapshot-chip strong { color: var(--text); font-weight: 600; }

/* ------------------------------------------------ nav tabs */
.view-tabs { display: flex; gap: 8px; padding: 16px 28px 0 28px; border-bottom: 1px solid var(--line); }
.view-tab {
  appearance: none; border: 0; background: transparent; color: var(--muted); cursor: pointer;
  font: 600 12.5px var(--sans); letter-spacing: 0.04em; padding: 10px 14px 12px;
  border-bottom: 2px solid transparent; margin-bottom: -1px;
}
.view-tab small { display: block; font-weight: 400; font-size: 10px; color: var(--faint); letter-spacing: 0.02em; }
.view-tab:hover { color: var(--text); }
.view-tab[aria-selected="true"] { color: var(--mint); border-bottom-color: var(--mint); }
.view-tab[aria-selected="true"] small { color: var(--mint); opacity: 0.75; }

/* ------------------------------------------------ KPI strip */
.kpi-strip {
  display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px;
  padding: 18px 28px 4px 28px;
}
.kpi {
  background: linear-gradient(180deg, var(--surface), var(--bg-2));
  border: 1px solid var(--line); border-radius: 14px; padding: 12px 14px 11px; position: relative; overflow: hidden;
}
.kpi::after {
  content: ""; position: absolute; inset: 0 0 auto 0; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(53, 224, 161, 0.5), transparent);
}
.kpi .label { font-size: 10px; text-transform: uppercase; letter-spacing: 0.12em; color: var(--muted); }
.kpi .value { font-family: var(--mono); font-size: 23px; margin-top: 5px; color: var(--text); }
.kpi .sub { font-size: 10.5px; color: var(--faint); margin-top: 2px; }
.kpi .value .unit { font-size: 12px; color: var(--muted); }
.kpi.hero .value { color: var(--mint); }

.honesty-strip {
  margin: 10px 28px 0; padding: 7px 12px; border: 1px dashed rgba(242, 193, 78, 0.35);
  border-radius: 10px; color: var(--gold); font-size: 11px; background: rgba(242, 193, 78, 0.05);
  display: flex; align-items: center; gap: 8px;
}
.honesty-strip strong { color: #ffe1a1; font-weight: 600; }

/* ------------------------------------------------ filter bar */
.filter-bar {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
  padding: 16px 28px 10px 28px;
}
.search-wrap { position: relative; flex: 1 1 240px; min-width: 200px; }
.search-wrap svg { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); opacity: 0.55; }
#search {
  width: 100%; background: var(--surface); border: 1px solid var(--line-strong); color: var(--text);
  border-radius: 10px; padding: 10px 12px 10px 36px; font: 13px var(--sans);
}
#search::placeholder { color: var(--faint); }
.seg { display: flex; background: var(--surface); border: 1px solid var(--line-strong); border-radius: 10px; overflow: hidden; }
.seg button {
  appearance: none; border: 0; background: transparent; color: var(--muted); cursor: pointer;
  font: 600 11.5px var(--sans); padding: 10px 14px; letter-spacing: 0.03em; border-right: 1px solid var(--line);
}
.seg button:last-child { border-right: 0; }
.seg button:hover { color: var(--text); }
.seg button[aria-pressed="true"] { background: var(--mint-dim); color: var(--mint); }
select.control {
  background: var(--surface); border: 1px solid var(--line-strong); color: var(--text);
  border-radius: 10px; padding: 10px 10px; font: 12px var(--sans); max-width: 190px;
}
.result-count { color: var(--muted); font-size: 11.5px; min-width: 118px; text-align: right; }
.result-count b { color: var(--text); }

.category-rail { display: flex; gap: 6px; overflow-x: auto; padding: 2px 28px 12px; scrollbar-width: thin; }
.cat-chip {
  appearance: none; white-space: nowrap; cursor: pointer; border: 1px solid var(--line); background: transparent;
  color: var(--muted); border-radius: 999px; font: 500 11px var(--sans); padding: 6px 12px; letter-spacing: 0.02em;
}
.cat-chip:hover { color: var(--text); border-color: var(--line-strong); }
.cat-chip[aria-pressed="true"] { background: var(--mint); border-color: var(--mint); color: #06281b; font-weight: 700; }

/* ------------------------------------------------ the board table */
.board-wrap { padding: 0 28px 28px; overflow-x: auto; }
table.board {
  width: 100%; border-collapse: collapse; font-size: 12.5px;
  background: var(--bg-2); border: 1px solid var(--line); border-radius: 14px; overflow: hidden;
}
.board thead th {
  text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: 0.11em; color: var(--muted);
  padding: 11px 12px; border-bottom: 1px solid var(--line-strong); background: rgba(16, 24, 48, 0.9);
  position: sticky; top: 0; z-index: 2; cursor: pointer; user-select: none; white-space: nowrap;
}
.board thead th:hover { color: var(--text); }
.board thead th .sort-mark { color: var(--mint); margin-left: 4px; }
.board thead th.num { text-align: right; }
.board tbody td { padding: 9px 12px; border-bottom: 1px solid var(--line); vertical-align: middle; }
.board tbody tr { transition: background 120ms ease; cursor: pointer; }
.board tbody tr:nth-child(even) { background: rgba(255, 255, 255, 0.015); }
.board tbody tr:hover { background: rgba(53, 224, 161, 0.06); }
.board tbody tr.watchlist-row td:first-child { box-shadow: inset 3px 0 0 var(--gold); }
.board tbody tr:focus-visible { outline: 2px solid var(--mint); outline-offset: -2px; }

.rank { font-family: var(--mono); color: var(--muted); width: 38px; }
.rank.top { color: var(--gold); font-weight: 700; }
.proto { display: flex; flex-direction: column; min-width: 150px; }
.proto .name { font-weight: 650; letter-spacing: 0.01em; }
.proto .chains { color: var(--faint); font-size: 10px; margin-top: 2px; }
.wl-badge {
  display: inline-block; vertical-align: 1px; margin-left: 7px; font-size: 8.5px; letter-spacing: 0.09em;
  color: #221a04; background: var(--gold); border-radius: 4px; padding: 1px 5px 2px; font-weight: 800;
}
.cat-tag { font-size: 10.5px; color: var(--muted); border: 1px solid var(--line); border-radius: 6px; padding: 2px 7px; white-space: nowrap; }
.num { text-align: right; font-family: var(--mono); font-variant-numeric: tabular-nums; }
.implied { text-align: right; }
.implied .value { font-family: var(--mono); font-size: 15px; font-weight: 650; color: #dcffe9; }
.implied .range { font-size: 9.5px; color: var(--faint); font-family: var(--mono); margin-top: 1px; }
.conf { display: inline-flex; align-items: center; gap: 6px; font-size: 10px; color: var(--muted); white-space: nowrap; }
.conf-dot { width: 8px; height: 8px; border-radius: 999px; display: inline-block; }
.conf-comp-backed .conf-dot { background: var(--mint); box-shadow: 0 0 6px rgba(53,224,161,.6); }
.conf-thin-comps .conf-dot { background: var(--gold); box-shadow: 0 0 6px rgba(242,193,78,.5); }
.conf-global-prior .conf-dot { background: var(--faint); }

/* interval whisker: log-scale low—implied—high against the board's own span */
.whisker { position: relative; width: 132px; height: 16px; }
.whisker .rail { position: absolute; top: 7px; left: 0; right: 0; height: 2px; background: rgba(148,184,255,.18); border-radius: 2px; }
.whisker .span { position: absolute; top: 5px; height: 6px; border-radius: 4px; background: linear-gradient(90deg, rgba(53,224,161,.25), rgba(53,224,161,.65)); }
.whisker .dot { position: absolute; top: 3px; width: 10px; height: 10px; border-radius: 999px; background: var(--mint); box-shadow: 0 0 8px rgba(53,224,161,.7); transform: translateX(-50%); }

.row-cta { color: var(--mint); font-size: 11px; white-space: nowrap; text-align: right; }
tr:hover .row-cta { text-decoration: underline; }

.empty-state { padding: 44px 20px; text-align: center; color: var(--muted); }
.empty-state b { color: var(--text); }

/* ------------------------------------------------ legend */
.legend { display: flex; gap: 16px; align-items: center; padding: 0 28px 14px 28px; color: var(--faint); font-size: 10.5px; flex-wrap: wrap; }
.legend span.item { display: inline-flex; gap: 6px; align-items: center; }

/* ------------------------------------------------ detail drawer */
.drawer-backdrop {
  position: fixed; inset: 0; background: rgba(3, 6, 14, 0.62); backdrop-filter: blur(3px);
  opacity: 0; pointer-events: none; transition: opacity 180ms ease; z-index: 40;
}
.drawer-backdrop.open { opacity: 1; pointer-events: auto; }
.drawer {
  position: fixed; top: 0; right: 0; height: 100vh; width: min(520px, 100vw); z-index: 50;
  background: linear-gradient(180deg, var(--surface), var(--bg-2) 30%);
  border-left: 1px solid var(--line-strong); box-shadow: -30px 0 80px rgba(0,0,0,.5);
  transform: translateX(102%); transition: transform 240ms cubic-bezier(.2,.8,.2,1);
  overflow-y: auto; padding: 20px 22px 40px;
}
.drawer.open { transform: translateX(0); }
.drawer-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.drawer h2 { font-family: var(--serif); font-weight: 600; font-size: 26px; margin: 0; line-height: 1.15; }
.slug { color: var(--faint); font-size: 11px; font-family: var(--mono); margin-top: 3px; }
.chip-row { display: flex; gap: 8px; margin: 10px 0 0; flex-wrap: wrap; }
.close-btn {
  appearance: none; border: 1px solid var(--line-strong); background: transparent; color: var(--muted);
  width: 34px; height: 34px; border-radius: 9px; cursor: pointer; font-size: 16px; flex: 0 0 auto;
}
.close-btn:hover { color: var(--text); border-color: var(--mint); }

.stat-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 16px 0; }
.stat { background: rgba(16,24,48,.55); border: 1px solid var(--line); border-radius: 12px; padding: 10px 11px; }
.stat .k { font-size: 9px; text-transform: uppercase; letter-spacing: 0.1em; color: var(--muted); }
.stat .v { font-family: var(--mono); font-size: 15px; margin-top: 4px; }
.stat .v small { font-size: 10px; color: var(--faint); }

.section-label {
  font-size: 10px; text-transform: uppercase; letter-spacing: 0.13em; color: var(--muted);
  border-top: 1px solid var(--line); padding-top: 16px; margin: 4px 0 10px;
}

/* waterfall: how the value was built */
.waterfall { display: flex; flex-direction: column; gap: 0; }
.wf-row { display: grid; grid-template-columns: 1fr auto; gap: 10px; padding: 7px 10px; border: 1px solid var(--line); border-bottom: 0; font-size: 11.5px; }
.wf-row:first-child { border-radius: 10px 10px 0 0; }
.wf-row:last-child { border-bottom: 1px solid var(--line); border-radius: 0 0 10px 10px; background: rgba(53,224,161,.06); }
.wf-row .eq { font-family: var(--mono); color: var(--mint); }
.wf-row .note { color: var(--faint); font-size: 10px; }
.backtest-line { margin: 10px 0 0; font-size: 10.5px; color: var(--muted); font-family: var(--mono); }
.backtest-line b { color: var(--gold); font-weight: 600; }

.caveat {
  display: flex; gap: 8px; align-items: flex-start; font-size: 11px; color: #ffd9a1;
  border: 1px solid rgba(242,193,78,.3); background: var(--gold-dim); border-radius: 10px;
  padding: 8px 10px; margin: 8px 0 0;
}

/* farm plan */
.farm-progress { display: flex; align-items: center; gap: 10px; margin: 6px 0 12px; }
.farm-progress .track { flex: 1; height: 6px; background: rgba(148,184,255,.12); border-radius: 3px; overflow: hidden; }
.farm-progress .fill { height: 100%; background: linear-gradient(90deg, var(--mint), #7ef0c8); width: 0%; transition: width 200ms ease; }
.farm-progress .n { font-family: var(--mono); font-size: 11px; color: var(--mint); min-width: 44px; text-align: right; }
.farm-step {
  display: flex; gap: 10px; padding: 9px 10px; border: 1px solid var(--line); border-radius: 10px;
  margin-bottom: 8px; align-items: flex-start; background: rgba(16,24,48,.35);
}
.farm-step input[type="checkbox"] { margin-top: 3px; accent-color: var(--mint); width: 15px; height: 15px; cursor: pointer; }
.farm-step.done .step-text { color: var(--faint); text-decoration: line-through; text-decoration-color: rgba(53,224,161,.4); }
.step-n { font-family: var(--mono); color: var(--gold); font-size: 10px; min-width: 16px; padding-top: 2px; }
.step-text { font-size: 11.5px; line-height: 1.5; }
.copy-btn {
  appearance: none; cursor: pointer; margin: 2px 0 0; border: 1px solid var(--line-strong); background: transparent;
  color: var(--mint); font: 600 11px var(--sans); border-radius: 8px; padding: 8px 12px; width: 100%;
}
.copy-btn:hover { background: var(--mint-dim); }
.drawer-disclaimer { color: var(--faint); font-size: 10px; line-height: 1.6; border-top: 1px solid var(--line); padding-top: 12px; margin-top: 14px; }

/* ------------------------------------------------ methodology modal */
.modal-backdrop {
  position: fixed; inset: 0; background: rgba(3,6,14,.7); backdrop-filter: blur(4px); z-index: 60;
  display: none; align-items: flex-start; justify-content: center; overflow-y: auto; padding: 40px 20px 60px;
}
.modal-backdrop.open { display: flex; }
.modal {
  max-width: 860px; width: 100%; background: linear-gradient(180deg, var(--surface-2), var(--surface));
  border: 1px solid var(--line-strong); border-radius: 18px; padding: 26px 30px 30px;
}
.modal h2 { font-family: var(--serif); font-size: 24px; margin: 0 0 2px; }
.modal h3 { font-size: 11px; text-transform: uppercase; letter-spacing: 0.13em; color: var(--mint); margin: 22px 0 8px; }
.modal p, .modal li { color: #c9d2e8; font-size: 12.5px; line-height: 1.6; }
.modal code, .modal pre {
  font-family: var(--mono); font-size: 11px; background: #0a0f22; border: 1px solid var(--line);
  border-radius: 8px; padding: 2px 6px; color: #a8f0cd;
}
.modal pre { display: block; padding: 12px 14px; overflow-x: auto; line-height: 1.6; }
.modal table { width: 100%; border-collapse: collapse; font-size: 11px; font-family: var(--mono); }
.modal th, .modal td { text-align: right; padding: 4px 8px; border-bottom: 1px solid var(--line); }
.modal th:first-child, .modal td:first-child { text-align: left; }
.modal th { color: var(--muted); font-weight: 600; text-transform: uppercase; font-size: 9px; letter-spacing: .08em; }
.bucket-row { display: grid; grid-template-columns: 90px 1fr 40px; align-items: center; gap: 10px; font-size: 10.5px; margin: 3px 0; }
.bucket-track { height: 10px; background: rgba(148,184,255,.1); border-radius: 2px; overflow: hidden; }
.bucket-fill { height: 100%; background: linear-gradient(90deg, #2a7f5f, var(--mint)); }
.modal-close-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; }

/* ------------------------------------------------ live reference view */
.live-banner { color: var(--muted); font-size: 11.5px; padding: 14px 28px 0; }
.live-banner b { color: var(--gold); }

/* ------------------------------------------------ footer */
.site-footer {
  border-top: 1px solid var(--line); padding: 16px 28px 22px; color: var(--faint); font-size: 10.5px;
  display: flex; justify-content: space-between; gap: 20px; flex-wrap: wrap; line-height: 1.7;
}
.site-footer b { color: var(--muted); }

/* ------------------------------------------------ responsive */
@media (max-width: 1100px) {
  .kpi-strip { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .site-header { flex-direction: column; align-items: flex-start; }
  .snapshot-chip { text-align: left; max-width: none; }
  .drawer { width: 100vw; }
}
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}
