const whiskerHtml = (r) => `
  <div class="whisker" role="img" aria-label="50% interval from ${fmtUsd(r.implied_value_low_usd)} to ${fmtUsd(r.implied_value_high_usd)}, implied ${fmtUsd(r.implied_value_usd)}">
