const copyPlan = (r) => {
  const lines = [
    `${r.name} — farm plan from the Token Launch Radar (board rank #${r.rank}, implied FDV ${fmtUsdFull(r.implied_value_usd)})`,
    ...r.farm_steps.map((s, i) => `${i + 1}. ${s}`),
